import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, Box3, Vector3, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, vec2, vec3, mix, fract, sin, dot, add, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};
  const timelines = [];

  // --- Lights ---
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 3);
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, -1, -2);
  root.add(rimLight);

  const ambientLight = new AmbientLight(0x404060, 0.6);
  root.add(ambientLight);

  // --- Backdrop ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const st = uv();
  const color1 = vec3(0.043, 0.043, 0.063); // #0b0b10
  const color2 = vec3(0.075, 0.075, 0.102); // #13131a
  const gradient = mix(color1, color2, st.y);
  const grain = fract(sin(dot(mul(st, 100.0), vec2(12.9898, 78.233))) * 43758.5453123);
  const grainAmount = 0.015;
  const finalColor = add(gradient, mul(sub(mul(grain, 2.0), 1.0), grainAmount));
  backdropMat.colorNode = finalColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.5;
  backdrop.position.y = 0;
  root.add(backdrop);

  // --- Hero Text: "TIME, MACHINED." ---
  const heroAtlas = ctx.fontAtlas.createText('TIME, MACHINED.', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -1.24
  });

  // Collect all glyph meshes, sorted left to right
  const allGlyphs = [];
  heroAtlas.traverse(child => {
    if (child.isMesh) allGlyphs.push(child);
  });
  allGlyphs.sort((a, b) => a.position.x - b.position.x);

  // Detect word boundary (gap > 0.03 units in atlas space)
  let gapIndex = allGlyphs.length;
  for (let i = 0; i < allGlyphs.length - 1; i++) {
    if (allGlyphs[i + 1].position.x - allGlyphs[i].position.x > 0.03) {
      gapIndex = i + 1;
      break;
    }
  }
  const firstWord = allGlyphs.slice(0, gapIndex);
  const secondWord = allGlyphs.slice(gapIndex);

  // Build per‑word groups with depth offsets
  const wordGroups = [];
  const zOffsets = [0.12, -0.12];
  [firstWord, secondWord].forEach((word, idx) => {
    const g = new Group();
    word.forEach(mesh => {
      const pos = mesh.position.clone();
      heroAtlas.remove(mesh);
      g.add(mesh);
      mesh.position.copy(pos);
    });
    g.position.z = zOffsets[idx];
    wordGroups.push(g);
  });

  // Hero line group, scaled so em height = 0.62 scene units
  const heroLineGroup = new Group();
  wordGroups.forEach(g => heroLineGroup.add(g));
  const scaleFactor = 0.005;
  heroLineGroup.scale.setScalar(scaleFactor);

  // Compute bounding box (world coords including scale) for centering
  const box = new Box3();
  wordGroups.forEach(g => {
    g.children.forEach(mesh => {
      const worldPos = new Vector3();
      mesh.getWorldPosition(worldPos);
      box.expandByPoint(worldPos);
    });
  });
  const centerX = (box.min.x + box.max.x) / 2;
  heroLineGroup.position.x = -centerX;
  heroLineGroup.position.y = 0.4;

  // Replace materials with PBR + initial opacity 0
  heroLineGroup.traverse(child => {
    if (child.isMesh) {
      const origColor = child.material.color || new Color('#e8ecf2');
      const newMat = new MeshStandardNodeMaterial();
      newMat.color = origColor;
      newMat.roughness = 0.5;
      newMat.metalness = 0.3;
      newMat.emissive = new Color('#000000');
      newMat.emissiveIntensity = 0;
      newMat.transparent = true;
      newMat.opacity = 0;
      newMat.needsUpdate = true;
      child.material = newMat;
    }
  });
  root.add(heroLineGroup);

  // --- Apply kinetic-text primitive (load trigger) ---
  const kineticResult = ctx.primitives['kinetic-text'](heroLineGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });
  timelines.push(kineticResult.timeline);

  // --- Weighted settle after final glyph lands ---
  const glyphCount = allGlyphs.length;
  const settleDelay = (glyphCount - 1) * 0.06 + 0.7;
  const settleTL = gsap.timeline({ delay: settleDelay });
  settleTL
    .set(heroLineGroup.scale, { x: scaleFactor * 1.04, y: scaleFactor * 1.04, z: scaleFactor * 1.04 })
    .to(heroLineGroup.scale, {
      x: scaleFactor,
      y: scaleFactor,
      z: scaleFactor,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    });
  timelines.push(settleTL);

  // --- Accent underline ---
  const textWidthWorld = box.max.x - box.min.x;
  const underlineWidth = 2.6;
  const underlineGeo = new PlaneGeometry(underlineWidth, 0.045);
  underlineGeo.translate(underlineWidth / 2, 0, 0);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new Color('#ff2a38');
  underlineMat.emissive = new Color('#ff2a38');
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 0.4;
  underlineMat.metalness = 0.6;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.y = -0.05;
  underline.position.x = box.min.x; // left edge relative to group
  underline.scale.x = 0;
  heroLineGroup.add(underline);

  const underlineDelay = settleDelay + 0.12;
  const underlineTL = gsap.to(underline.scale, {
    x: 1,
    duration: 0.5,
    delay: underlineDelay,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  });
  timelines.push(underlineTL);

  // --- Subhead ---
  const subheadAtlas = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.8
  });
  subheadAtlas.scale.setScalar(0.005);
  subheadAtlas.position.y = -0.65;
  subheadAtlas.traverse(child => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
      child.material.needsUpdate = true;
    }
  });
  root.add(subheadAtlas);

  // Animate position and opacity
  const subheadTL = gsap.to(subheadAtlas.position, {
    y: -0.65,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    delay: 0.5,
    startAt: { y: -0.45 }
  });
  timelines.push(subheadTL);

  subheadAtlas.traverse(child => {
    if (child.isMesh) {
      const matTL = gsap.to(child.material, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: 0.5
      });
      timelines.push(matTL);
    }
  });

  // --- Caption ---
  const captionAtlas = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2.16
  });
  captionAtlas.scale.setScalar(0.005);
  captionAtlas.position.y = 1.15;
  root.add(captionAtlas);

  // --- Cleanup ---
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    kineticResult.cleanup();
    // dispose geometries/materials if needed (optional)
  };

  return root;
}
